import { test, expect } from '@playwright/test';

test.describe('Numeric Column Summary Row', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-list');
  });

  test('should display summary row at the bottom of numeric column when data is present', async ({ page }) => {
    // Setup: Load table with numeric data
    await page.route('**/api/table-data', route => {
      route.continue();
    });

    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify summary row is not visible initially
    const summaryRow = page.getByRole('row', { name: /summary/i });
    await expect(summaryRow).not.toBeVisible();

    // Verify table headers are present
    const headers = page.getByRole('rowheader', { name: /column 1|column 2|column 3/i });
    await expect(headers).toBeVisible();

    // Verify numeric data rows are present
    const dataRows = page.getByRole('row', { name: /row 1|row 2|row 3/i });
    await expect(dataRows).toHaveCount(3);

    // Verify summary row is visible after data is loaded
    await page.waitForResponse(response => response.url().includes('/api/table-data') && response.status() === 200);
    await expect(summaryRow).toBeVisible();

    // Verify summary row contains correct data
    const summaryCell = page.getByRole('cell', { name: /total/i });
    await expect(summaryCell).toContainText('Total');

    const summaryValue = page.getByRole('cell', { name: /1000/i });
    await expect(summaryValue).toContainText('1000');

    // Verify summary row is styled appropriately
    await expect(summaryRow).toHaveClass(/summary-row/);
  });

  test('should not display summary row when no data is present', async ({ page }) => {
    // Setup: Disable data source
    await page.route('**/api/table-data', route => {
      route.abort();
    });

    // Verify table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify summary row is not visible when no data
    const summaryRow = page.getByRole('row', { name: /summary/i });
    await expect(summaryRow).not.toBeVisible();

    // Verify table headers are present
    const headers = page.getByRole('rowheader', { name: /column 1|column 2|column 3/i });
    await expect(headers).toBeVisible();

    // Verify summary row is still not visible
    await expect(summaryRow).not.toBeVisible();

    // Verify summary row is not styled
    await expect(summaryRow).not.toHaveClass(/summary-row/);
  });
});
